function hullContains(x,y,points){let inside=false;for(let i=0,j=points.length-1;i<points.length;j=i++){let a=points[i],b=points[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
const PLAYER_MASS=4;
const PLAYER_HULL_SIZE=.65; // World units, shared by mining, combat and recovery.
// Authored size multipliers are independent of physical mass (player size = 1).
function alienMass(style){return ALIEN_SOURCE[((style??0)%25+25)%25].mass}
function alienSize(style){let rect=SHIP_SPRITE_RECTS[((style??0)%25+25)%25];return PLAYER_HULL_SIZE*1.3*202/(2.5*1.2*Math.max(rect[2],rect[3]))*ALIEN_SOURCE[((style??0)%25+25)%25].sizeMultiplier}
function alienRadius(m){return Math.max(...ALIEN_HULLS[m.style??0].tiles.map(([x,y])=>Math.hypot(x,y)+.36))*alienSize(m.style)}
