function alienHullBlocks(style,totalHp){let tiles=ALIEN_HULLS[style%25].tiles,size=alienSize(style);return tiles.map(([x,y])=>({x:x*size,y:y*size,hp:totalHp/tiles.length,max:totalHp/tiles.length}))}
