const SHIP_SPRITE_RECTS=[[13,20,188,216],[243,22,129,217],[424,89,180,136],[636,20,172,224],[828,21,182,224],[10,270,194,205],[221,261,171,203],[423,272,177,191],[630,268,184,206],[835,268,167,212],[12,500,185,218],[239,499,133,240],[413,493,197,229],[646,500,154,222],[832,507,174,219],[15,740,178,232],[214,762,183,195],[456,742,112,218],[643,742,158,229],[829,771,180,190],[12,991,182,235],[217,1017,178,191],[415,1005,193,216],[624,1041,199,179],[843,992,150,230],[4,1264,199,202]];
function drawAtlasShip(index,size,factor){
 let [x,y,w,h]=SHIP_SPRITE_RECTS[index],cellW=1024/5,cellH=1536/6,scale=size*factor*2/cellH;
 // Preserve atlas coordinates so custom crops cannot shift hulls or engines.
 let originX=index%5*cellW,originY=Math.floor(index/5)*cellH;
 ctx.save();ctx.shadowBlur=0;ctx.drawImage(alienFleetSprite,x,y,w,h,(-cellW/2+x-originX)*scale,(-cellH/2+y-originY)*scale,w*scale,h*scale);ctx.restore();
}


function collideAlienProjectiles(dt){
 let e=encounter;for(let incoming of e.shots){if(incoming.enemy||incoming.life<=0||incoming.weapon===3||incoming.weapon===9)continue;
  for(let q of e.shots){if(!q.enemy||q.life<=0||!q.hp)continue;let dx=incoming.x-q.x,dy=incoming.y-q.y,vx=incoming.vx-q.vx,vy=incoming.vy-q.vy,t=Math.max(0,Math.min(dt,-(dx*vx+dy*vy)/(vx*vx+vy*vy||1)));if(Math.hypot(dx+vx*t,dy+vy*t)>(q.radius||.12)+.12)continue;
   let damage=Math.max(0,incoming.damage||0)/Math.max(.001,alienPower()),enemyDamage=q.baseHp; q.hp-=damage;incoming.hp=(incoming.hp??1)-enemyDamage;if(incoming.hp<=0)incoming.life=0;if(q.hp<=0){q.life=0;e.effects.push({kind:'burst',x:q.x,y:q.y,color:q.color,age:0,life:.18,radius:.5});}break;
  }
 }
}

const ALIEN_WEAPON_SPRITES={fusion:0,disc:1,plasma:2,howitzer:3,crystal:4,globule:5,flame:6,mass:7,confusion:12,missile:13,rear:13,bubble:14,limpet:15,particle:16,dart:17,battery:18,twin:18,triple:19,torch:20,spray:21,shard:22,fire:23,fireCloud:23,drainer:24};
function drawWeaponSprite(index,x,y,width,height,angle=0,opacity=1){if(!alienWeaponSprite.complete||!alienWeaponSprite.naturalWidth)return false;let [sx,sy,w,h]=ALIEN_WEAPON_RECTS[index];ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.globalAlpha*=opacity;ctx.drawImage(alienWeaponSprite,sx,sy,w,h,-width/2,-height/2,width,height);ctx.restore();return true;}

function drawAlienBeamEffect(f,cx,cy,z){
 if(!['beam','laser','lightning','tongue','tractor'].includes(f.kind)||Number.isInteger(f.playerWeapon))return false;
 let x=cx+f.x*z,y=cy+f.y*z,dx=(f.x2-f.x)*z,dy=(f.y2-f.y)*z,len=Math.hypot(dx,dy);ctx.save();ctx.globalAlpha=Math.max(0,1-f.age/f.life);ctx.strokeStyle=f.color||'#d9ffff';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=z*.25;ctx.lineWidth=Math.max(.6,z*(f.kind==='tongue'?.25:.07));ctx.beginPath();ctx.moveTo(x,y);
 if(f.kind==='lightning'){let nx=-dy/(len||1),ny=dx/(len||1);for(let j=1;j<16;j++){let noise=Math.sin(j*7+(f.seed||0)+encounter.elapsed*65)*z*.22;ctx.lineTo(x+dx*j/16+nx*noise,y+dy*j/16+ny*noise);}ctx.lineTo(x+dx,y+dy);}
 else if(f.kind==='tractor'){for(let j=1;j<=20;j++){let n=Math.sin(j*1.5-encounter.elapsed*16)*z*.18;ctx.lineTo(x+dx*j/20-dy/(len||1)*n,y+dy*j/20+dx/(len||1)*n);}}
 else ctx.lineTo(x+dx,y+dy);ctx.stroke();if(f.kind!=='tractor'){ctx.shadowBlur=0;ctx.strokeStyle='#ffffff';ctx.lineWidth=Math.max(.4,z*.025);ctx.stroke();}ctx.restore();return true;
}

