function breakthroughCount(level){if(level<10)return 0;if(level<25)return 1;if(level<50)return 2;if(level<75)return 3;if(level<100)return 4;return 5+Math.floor((level-100)/50)}
function breakthroughLevel(count){return count<5?[10,25,50,75,100][count]:100+(count-4)*50}
function breakthroughMultiplier(){return 2**s.breakthroughClaims.reduce((total,count)=>total+Math.max(0,count-1),0)}
function syncBreakthroughs(){let earned=0;for(let i=0;i<10;i++){if(!(s.ownedWeapons&(1<<i)))continue;let reached=breakthroughCount(s.weaponLevels[i]),extra=Math.max(0,reached-s.breakthroughClaims[i]);if(extra){s.breakthroughClaims[i]=reached;earned+=extra}}s.spaceGems+=earned;return earned}
