let runtimeErrorCount=0;
function reportRuntimeError(error){console.error('Orbit Forge:',error);let card=$('runtimeError');if(!card){card=document.createElement('div');card.id='runtimeError';card.style.cssText='position:absolute;left:8px;right:8px;bottom:48px;z-index:30;padding:8px;background:#102028ee;color:#ffd4b2;font:11px monospace;overflow-wrap:anywhere';view.appendChild(card)}card.textContent='Game error: '+(error?.message||String(error));card.hidden=false}
function recoverMotion(){for(let p of [ship,...drones,...(encounter?.ships||[]),...(encounter?.combatDrones||[]),...(encounter?.player?[encounter.player]:[])]){if(!Number.isFinite(p.x))p.x=0;if(!Number.isFinite(p.y))p.y=-planetRadius()-4;if(!Number.isFinite(p.a))p.a=0;if(!Number.isFinite(p.vx))p.vx=0;if(!Number.isFinite(p.vy))p.vy=0;if(!Number.isFinite(p.thrust))p.thrust=0}if(!Number.isFinite(camera.x))camera.x=ship.x;if(!Number.isFinite(camera.y))camera.y=ship.y}
function frame(realTime){try{let elapsed=Math.min(.05,Math.max(0,(realTime-last)/1000))*dev.speed;last=realTime;let steps=Math.max(1,Math.ceil(elapsed/.02)),dt=elapsed/steps;for(let n=0;n<steps;n++){if((!encounter||encounter.type==='asteroid')&&!s.devPlanetReady)simulationTime+=dt*1000;stepFrame(simulationTime,dt)}runtimeErrorCount=0;let card=$('runtimeError');if(card)card.hidden=true}catch(error){runtimeErrorCount++;recoverMotion();try{if(encounter?.type==='merchant')drawMerchant();else draw(simulationTime)}catch(drawError){console.error(drawError)}reportRuntimeError(error)}finally{requestAnimationFrame(frame)}}

function drawMini(){let m=$('mini');if(!m)return;let q=m.getContext('2d'),scale=22/planetRadius();q.clearRect(0,0,48,48);q.fillStyle='#071419';q.fillRect(0,0,48,48);q.fillStyle='#35b7bf';for(const c of cells)if(c.hp>0)q.fillRect(24+c.x*scale,24+c.y*scale,Math.max(.35,scale),Math.max(.35,scale))}
function systemPlanetCount(system){
 let seed=(Math.imul(system,2654435761)^Math.imul(s.universe,2246822519))>>>0;seed=(Math.imul(seed,1664525)+1013904223)>>>0;
 let weights=Array.from({length:20},(_,i)=>Math.exp(-.5*((i+1-10)/3)**2)),total=weights.reduce((a,b)=>a+b,0),roll=seed/4294967296*total;
 for(let i=0;i<20;i++){roll-=weights[i];if(roll<=0)return i+1}return 20;
}
function starLocation(){let planet=s.planet,system=1,total=systemPlanetCount(system);while(planet>total){planet-=total;system++;total=systemPlanetCount(system)}return {system,planet,total}}
function multiplierLabel(){let value=mult();return (value<1000?Number(value.toFixed(2)).toString():fmt(value))+'×'}
function renderUI(){renderSurveyToolbar();drawMini();const total=cells.length||1;$('bar').style.width=(100*alive/total)+'%';$('bar').parentElement.setAttribute('aria-valuenow',Math.ceil(100*alive/total));$('credits').textContent=dev.credits?'∞':fmt(s.credits);$('spaceGems').textContent=dev.aether?'∞':fmt(s.spaceGems);let location=starLocation();$('planetLabel').textContent=encounter?.type==='asteroid'?'ASTEROID':location.planet+'/'+location.total;$('systemLabel').textContent=location.system;$('universeLabel').textContent=s.universe;$('overallMultiplier').textContent=multiplierLabel();renderPanel()}
function card(name,detail,value,label,disabled,action){return `<div class="card"><div class="row"><div><div class="title">${name} <span class="pill">${value}</span></div><div class="desc">${detail}</div></div><button class="buy" data-action="${action}" ${disabled?'disabled':''}>${label}</button></div></div>`}
const SCANNER_KEYS={ore:'oreScanner',flora:'plantScanner',fauna:'creatureScanner',tech:'alienScanner'};
const SCANNER_NAMES={ore:'Ore Scanner',flora:'Plant Life Scanner',fauna:'Creature Scanner',tech:'Alien Tech Scanner'};
const LIFE_SPECIES=[['Cinderback Mite',1],['Lumen Spore',1],['Glassfin Crawler',1],['Frostveil Lichen',1],['Emberwing Nymph',2],['Copperroot Mycelium',2],['Prism Shell Larva',2],['Aurora Ribbonworm',2],['Voidlace Polyp',3],['Starwhisper Orchid',3],['Gravitide Medusa',4],['Aetherglass Leviathan Egg',4]];
for(const [name] of LIFE_SPECIES)if(!['Lumen Spore','Frostveil Lichen','Copperroot Mycelium','Voidlace Polyp','Starwhisper Orchid'].some(base=>name===base||name.includes(' '+base+' · U'))&&s.inventory[name]){s.inventory[name+' bio info']=(s.inventory[name+' bio info']||0)+s.inventory[name];delete s.inventory[name]}
const RESOURCE_TIERS=[['Copper','Silver','Quartz','Amethyst'],['Gold','Platinum','Topaz','Sapphire'],['Obsidian','Cobalt','Emerald','Ruby'],['Palladium','Titanium','Mystic Topaz','Diamond']];
function planetTierWeights(planet){let focus=Math.min(3,Math.max(0,(planet-1)/8)),weights=[0,1,2,3].map(t=>Math.exp(-1.4*(t-focus)**2)+.008);let sum=weights.reduce((a,b)=>a+b,0);return weights.map((w,i)=>[.12,.1,.08,.06][i]+.64*w/sum)}
function resourceDeposit(j){if(j<4)return [RESOURCE_TIERS[0][j],1,j<2?30:8];let weights=planetTierWeights(s.planet),roll=discoveryRandom(1200+j),tier=0;while(tier<3&&roll>weights[tier])roll-=weights[tier++];let names=RESOURCE_TIERS[tier],slot=Math.floor(discoveryRandom(1300+j)*4),name=names[slot],rarity=Math.min(4,tier+1),base=slot<2?[30,22,16,10][tier]:[8,7,6,5][tier];return [name,rarity,base]}
function lifeName(base){let prefix=['Luminous','Veiled','Prismatic','Ember','Azure','Violet','Frost','Copper','Glass','Dusk'][Math.floor(discoveryRandom(1600)*10)];return prefix+' '+base+' · U'+s.universe+' P'+s.planet}
if(s.inventory['Iron ore']){s.inventory.Silver=(s.inventory.Silver||0)+s.inventory['Iron ore'];delete s.inventory['Iron ore']}
const ORE_CLASSES=[{name:'Rocky',items:[['Silver',1,22],['Copper',1,32],['Quartz',1,5],['Emerald',3,3]]},{name:'Metallic',items:[['Silver',1,24],['Copper',1,34],['Titanium',3,7],['Quartz',1,8]]},{name:'Crystalline',items:[['Quartz',1,12],['Emerald',2,4],['Sapphire',3,3],['Amethyst',4,2]]},{name:'Volcanic',items:[['Copper',1,32],['Silver',1,22],['Titanium',3,7],['Quartz',1,8]]},{name:'Frozen',items:[['Silver',1,20],['Quartz',1,12],['Sapphire',2,4],['Emerald',3,3]]},{name:'Alien',items:[['Copper',1,28],['Quartz',1,12],['Exotic Matter',3,2],['Amethyst',4,2]]}];
const TECH_ITEMS=[['Ancient Relay Fragment',1],['Dormant Alien Circuit',1],['Alien conductor',1],['Phase Lattice',3],['Singularity Seed',4],['Bio-Neural Matrix',2],['Graviton Lens',2],['Quantum Memory Core',3]];
function discoveryRandom(salt){let n=(Math.imul(s.planet,2654435761)^Math.imul(s.universe,2246822519)^Math.imul(salt+1,3266489917))>>>0;n=Math.imul(n^(n>>>16),2246822507)>>>0;n=Math.imul(n^(n>>>13),3266489909)>>>0;return ((n^(n>>>16))>>>0)/4294967296}
function planetClass(){return ORE_CLASSES[Math.floor(discoveryRandom(901)*ORE_CLASSES.length)]}
function scannerRarity(level){return level>=10?4:level>=6?3:level>=3?2:1}
function generateDiscoveries(){for(const key of Object.values(SCANNER_KEYS))s[key]=Math.max(0,Math.floor(s[key]||0));
 discoveries=[];scanLevels={ore:0,flora:0,fauna:0,tech:0};let old=s.grid&&s.grid.planet===s.planet?s.grid:null,used=new Set(),klass=planetClass();
 function site(kind,name,rarity,base,salt){let pool=cells.filter(c=>c.body!=='ring'),index=Math.floor(discoveryRandom(salt)*pool.length);while(used.has(index))index=(index+1)%pool.length;used.add(index);let c=pool[index];discoveries.push({id:discoveries.length,kind,name,rarity,base,x:c.x,y:c.y,collected:0})}
 for(let j=0;j<12;j++){let item=resourceDeposit(j);site('ore',item[0],item[1],item[2],100+j)}
 for(let j=0;j<8;j++){let item=LIFE_SPECIES[Math.floor(discoveryRandom(200+j)*LIFE_SPECIES.length)];site(['Lumen Spore','Frostveil Lichen','Copperroot Mycelium','Voidlace Polyp','Starwhisper Orchid'].includes(item[0])?'flora':'fauna',lifeName(item[0]),item[1],2+Math.floor(discoveryRandom(400+j)*4),200+j)}
 // Buried alien caches are sparse; future wrecks use the same scanner rules.
 let techCount=klass.name==='Alien'?5:discoveryRandom(701)<.35?2:0;
 for(let j=0;j<techCount;j++){let item=TECH_ITEMS[Math.floor(discoveryRandom(300+j)*5)];site('tech',item[0],item[1],item[1]===1?3:2,300+j)}
 if(!discoveries.some(d=>d.kind==='tech'&&d.name==='Ancient Relay Fragment'))site('tech','Ancient Relay Fragment',1,3,799);
 site('tech','Dormant Alien Circuit',1,2,811);site('tech','Alien conductor',1,2,812);let advanced=TECH_ITEMS[5+Math.floor(discoveryRandom(813)*3)];site('tech',advanced[0],advanced[1],1,813);
 // Duplicate the original life and tech site mix at distinct locations.
 const extraScannables=discoveries.filter(d=>d.kind!=='ore').map(d=>({...d}));
 extraScannables.forEach((d,j)=>site(d.kind,d.name,d.rarity,d.base,900+j));
 // Append the additional deposits to preserve existing discovery IDs in saves.
 for(let j=12;j<24;j++){let item=resourceDeposit(j);site('ore',item[0],item[1],item[2],100+j)}
 if(old&&old.scanLevels)for(const kind of Object.keys(SCANNER_KEYS))scanLevels[kind]=Math.max(0,Math.min(s[SCANNER_KEYS[kind]],Number(old.scanLevels[kind])||0));
 if(old&&Array.isArray(old.discoveryCollected))discoveries.forEach((d,i)=>d.collected=Math.max(0,Number.isSafeInteger(old.discoveryCollected[i])?old.discoveryCollected[i]:0));
 autoScanPlanet();
}
function scannerYieldFactor(level){return 1+.2*Math.log2(Math.max(1,level))}
function limitedTechQuantity(n){return Math.max(1,Math.min(2,Math.floor(n)))}
function discoveryQuantity(d,level){let factor=scannerYieldFactor(level)*(upgradeHas('scanner-optics')?1.25:1)*bioFactor(SCANNER_KEYS[d.kind])*equipmentFactor('yield')*universeFactor('scanning',.05)*(upgradeHas({flora:'flora-cultures',fauna:'fauna-stasis',tech:'alien-decoder'}[d.kind])?1.25:1),quantity=d.base*(d.kind==='ore'?.45:.5)*factor;return d.kind==='tech'?limitedTechQuantity(quantity):Math.max(1,Math.floor(quantity))}

function discoveryVisible(d){return scanLevels[d.kind]>0&&d.rarity<=scannerRarity(scanLevels[d.kind])&&cellMap.get(d.x+','+d.y)?.hp>0}
function autoScanPlanet(){if(!upgradeHas('targeting-auto-scan')||s.targeting<1)return;for(const [kind,key] of Object.entries(SCANNER_KEYS))if(s[key]>0)scanLevels[kind]=Math.max(scanLevels[kind]||0,s[key])}
function scanDiscoveries(kind){let level=s[SCANNER_KEYS[kind]];if(!level||planetTransit)return;scanLevels[kind]=Math.max(scanLevels[kind],level);let found=discoveries.filter(d=>d.kind===kind&&discoveryVisible(d)).length;notice(SCANNER_NAMES[kind].toUpperCase()+' · '+found+' SITES DETECTED');renderUI();save()}
function recoverDiscoveryAt(c){for(const d of discoveries){if(d.x!==c.x||d.y!==c.y||!scanLevels[d.kind]||d.rarity>scannerRarity(scanLevels[d.kind]))continue;let amount=Math.max(0,discoveryQuantity(d,scanLevels[d.kind])-d.collected);if(!amount)continue;d.collected+=amount;let name=d.kind==='fauna'?d.name+' bio info':d.name,stored=storeCargo(name,amount);notice(stored?'+'+stored+' '+name:'CARGO FULL')}if(resourceTarget&&resourceTarget.x===c.x&&resourceTarget.y===c.y)resourceTarget=null}
function nearestScannedItem(){return discoveries.filter(d=>discoveryVisible(d)&&d.collected<discoveryQuantity(d,scanLevels[d.kind])).sort((a,b)=>Math.hypot(a.x+.5-ship.x,a.y+.5-ship.y)-Math.hypot(b.x+.5-ship.x,b.y+.5-ship.y))[0]||null}
function autoSurveyTarget(){if(s.autoSurvey&&s.targeting>0&&!resourceTarget&&!planetTransit&&!encounter){resourceTarget=nearestScannedItem();if(resourceTarget){resourceStep=null;lockedTarget=null;turnState=null}}}
function collectDiscoveries(kind){if(planetTransit)return;if(resourceTarget?.kind===kind){resourceTarget=null;lockedTarget=null;notice('MINING RESUMED');renderUI();return}let options=discoveries.filter(d=>d.kind===kind&&discoveryVisible(d)&&d.collected<discoveryQuantity(d,scanLevels[kind]));options.sort((a,b)=>Math.hypot(a.x+.5-ship.x,a.y+.5-ship.y)-Math.hypot(b.x+.5-ship.x,b.y+.5-ship.y));resourceTarget=options[0]||null;resourceStep=null;lockedTarget=null;turnState=null;notice(resourceTarget?'MINING TOWARD '+resourceTarget.name:'NO DISCOVERIES AVAILABLE');renderUI()}
// Collection clears a three-block-wide corridor; normal orbit clearance is unchanged.
function resourceBlockDistance(c,x,y){return Math.hypot(x-Math.max(c.x,Math.min(c.x+1,x)),y-Math.max(c.y,Math.min(c.y+1,y)))}
function resourceMiningTarget(){
 resourceStep=null;if(!resourceTarget)return null;if(!discoveryVisible(resourceTarget)){resourceTarget=null;return null}
 let dx=resourceTarget.x+.5-ship.x,dy=resourceTarget.y+.5-ship.y,length=Math.hypot(dx,dy)||1;
 let step=Math.min(.6,length),x=ship.x+dx/length*step,y=ship.y+dy/length*step;
 let blockers=cells.filter(c=>c.hp>0&&resourceBlockDistance(c,x,y)<1.5);
 if(!blockers.length){resourceStep={x,y};return null}
 // Mine the closest reachable block to the resource first, within the required corridor.
 // Once that opening is clear, remove only walls preventing the next movement step.
 let tx=resourceTarget.x+.5,ty=resourceTarget.y+.5;
 let corridor=cells.filter(c=>{if(c.hp<=0)return false;let along=Math.max(0,Math.min(length,((c.x+.5-ship.x)*dx+(c.y+.5-ship.y)*dy)/length));return resourceBlockDistance(c,ship.x+dx/length*along,ship.y+dy/length*along)<1.5});
 let reachable=corridor.filter(c=>exposed(c)&&clearShot(c)&&shotDistance(c)<=weaponRange(0));
 if(reachable.includes(lockedTarget))return lockedTarget;
 reachable.sort((a,b)=>Math.hypot(a.x+.5-tx,a.y+.5-ty)-Math.hypot(b.x+.5-tx,b.y+.5-ty)||shotDistance(a)-shotDistance(b));
 if(reachable.length)return reachable[0];
 // A side wall can block movement even when it falls outside the forward corridor.
 // Clear the first visible wall on the way to an actual movement blocker.
 let walls=[];for(const blocker of blockers){let bx=blocker.x+.5,by=blocker.y+.5,n=Math.max(1,Math.ceil(Math.hypot(bx-ship.x,by-ship.y)/.1));for(let j=1;j<=n;j++){let wall=cellMap.get(Math.floor(ship.x+(bx-ship.x)*j/n)+','+Math.floor(ship.y+(by-ship.y)*j/n));if(wall&&wall.hp>0){if(!walls.includes(wall)&&canWeaponTarget(wall,0))walls.push(wall);break}}}
 walls.sort((a,b)=>Math.hypot(a.x+.5-tx,a.y+.5-ty)-Math.hypot(b.x+.5-tx,b.y+.5-ty));if(walls.length)return walls.includes(lockedTarget)?lockedTarget:walls[0];
 // Rounded collision clearance can include a side/corner wall missed by the centre ray.
 // Never brake indefinitely without an attackable block to open the corridor.
 let nearby=cells.filter(c=>canWeaponTarget(c,0));
 nearby.sort((a,b)=>Number(blockers.includes(b))-Number(blockers.includes(a))||resourceBlockDistance(a,x,y)-resourceBlockDistance(b,x,y)||Math.hypot(a.x+.5-tx,a.y+.5-ty)-Math.hypot(b.x+.5-tx,b.y+.5-ty));
 if(nearby.length)return nearby[0];
 // If already touching rock, its exposed boundary is the immediate obstruction.
 let touching=blockers.filter(c=>canWeaponTarget(c,0));
 touching.sort((a,b)=>shotDistance(a)-shotDistance(b));return touching[0]||null;
}
function moveResourceShip(dt){turnState=null;nextAboutFace=simulationTime+8500;let beforeX=ship.x,beforeY=ship.y;if(resourceStep){let dx=resourceStep.x-ship.x,dy=resourceStep.y-ship.y,length=Math.hypot(dx,dy),speed=shipSpeed();flyAlien(ship,length>1e-6?dx/length*speed:0,length>1e-6?dy/length*speed:0,speed,turnRate(),dt)}else flyAlien(ship,0,0,shipSpeed(),turnRate(),dt);if(cells.some(c=>c.hp>0&&resourceBlockDistance(c,ship.x,ship.y)<1.49)){ship.x=beforeX;ship.y=beforeY;ship.vx=0;ship.vy=0;ship.thrust=0}}

const SURVEY_SYMBOLS={ore:'◆',flora:'♧',fauna:'🐾',tech:'⌬'},SURVEY_COLORS={ore:'#ffce79',flora:'#99f58a',fauna:'#ffac89',tech:'#c7a2ff'};
function renderSurveyToolbar(){let toolbar=$('surveyToolbar');if(!toolbar)return;if(encounter?.type==='merchant'){toolbar.innerHTML='';return}toolbar.innerHTML=Object.keys(SCANNER_KEYS).filter(kind=>s[SCANNER_KEYS[kind]]>0).map(kind=>{let level=s[SCANNER_KEYS[kind]];return `<div class="survey-tool" style="--scan-color:${SURVEY_COLORS[kind]}"><button data-action="scan:${kind}" title="Scan with ${SCANNER_NAMES[kind]}, then tap a resource to mine toward it" aria-label="Scan with ${SCANNER_NAMES[kind]}" ${!level||planetTransit?'disabled':''}>${SURVEY_SYMBOLS[kind]}<small>LV ${level}</small></button></div>`}).join('')+(s.targeting>0?`<div class="survey-tool" style="--scan-color:#f1d47e"><button data-action="autoSurvey" aria-label="Automatically mine nearest scanned item" title="Mine nearest scanned item" ${planetTransit?'disabled':''}>⌖<small>${s.autoSurvey?'AUTO ON':'AUTO'}</small></button></div>`:'')}
function resourceAtScreenPoint(x,y){let w=cv.clientWidth,h=cv.clientHeight,scale=mapScale(),cx=w/2-camera.x*scale,cy=h*.38-camera.y*scale,best=null,distance=Math.max(18,scale*.85);for(const d of discoveries){if(!discoveryVisible(d)||d.collected>=discoveryQuantity(d,scanLevels[d.kind]))continue;let gap=Math.hypot(cx+(d.x+.5)*scale-x,cy+(d.y+.5)*scale-y);if(gap<distance){distance=gap;best=d}}return best}
function selectResource(d){if(!d||planetTransit||!discoveryVisible(d))return;resourceTarget=resourceTarget===d?null:d;resourceStep=null;lockedTarget=null;turnState=null;notice(resourceTarget?'MINING TOWARD '+resourceTarget.name:'RESUMING NORMAL MINING');renderUI()}


let dumpAmount=1;
function dumpQuantity(owned){return dumpAmount==='max'?owned:Math.min(owned,dumpAmount)}
function dumpInventory(name,equipment=false){let g=equipment?EQUIPMENT.find(g=>g.id===name):null;if(equipment&&!g)return;let owned=equipment?spareEquipmentCount(g):Math.max(0,s.inventory[name]||0),n=dumpQuantity(owned);if(!Number.isSafeInteger(n)||n<1)return;if(equipment)s.equipmentInventory[g.id]-=n;else{s.inventory[name]-=n;if(s.inventory[name]<=0)delete s.inventory[name];}renderUI();save();notice('DUMPED '+fmt(n)+' '+(g?g.name:name));}
function renderLiveInventory(){let used=cargoUsed(),capacity=cargoCapacity();let html=`<div class="milestone-label">Cargo ${fmt(used)} / ${fmt(capacity)} · Free ${fmt(Math.max(0,capacity-used))}</div><div class="trade-quantity">`+[1,10,100,1000,'max'].map(n=>`<button class="${dumpAmount===n?'selected':''}" data-action="dumpAmount:${n}">${String(n).toUpperCase()}</button>`).join('')+'</div>';let item=(name,owned,action)=>`<div class="cargo-item cargo-dump"><span>${htmlSafe(name)}</span><b>${fmt(owned)}</b><button class="buy" data-action="${action}" aria-label="Discard ${dumpQuantity(owned)} ${htmlSafe(name)}">DUMP ${fmt(dumpQuantity(owned))}</button></div>`;for(let type of ['Ores','Gems','Materials','Plants','Bio information','Alien tech']){let items=Object.entries(s.inventory).filter(([name,n])=>n>0&&tradeType(name)===type).sort(([a],[b])=>a.localeCompare(b));if(items.length)html+=`<div class="panel-heading">${type}</div><div class="inventory-grid">`+items.map(([name,n])=>item(name,n,'dumpCargo:'+encodeURIComponent(name))).join('')+'</div>';}let spares=EQUIPMENT.filter(g=>spareEquipmentCount(g)>0);if(spares.length)html+='<div class="panel-heading">Spare equipment</div><div class="inventory-grid">'+spares.map(g=>item(g.name,spareEquipmentCount(g),'dumpEquipment:'+encodeURIComponent(g.id))).join('')+'</div>';return html}


