let craftTab='recipes',sampleCargo=false,previewCrafted=[],previewFitted='';
const sampleMaterials={'Silver':156,'Copper':280,'Emerald':24,'Hardened alloy':36,'Navigation tech':12,'Titanium':18,'Sapphire':6,'Alien conductor':0};
let previewCargo={...sampleMaterials};
const PREVIEW_RECIPES=[{name:'Boomerang Blade',desc:'A sweeping blade that strikes many blocks along an arc.',recipe:{'Hardened alloy':30,'Emerald':20,'Navigation tech':10}},{name:'Scatter Cannon',desc:'A spread of projectiles for clearing clustered blocks.',recipe:{'Silver':200,'Copper':350,'Emerald':30}}];
function previewHasRecipe(r){return sampleCargo&&Object.entries(r.recipe).every(([name,n])=>(previewCargo[name]||0)>=n)}
function canPayCost(cost){return (dev.credits||s.credits>=cost.credits)&&Object.entries(cost.materials||{}).every(([name,n])=>dev.materials||craftOwned(name)>=n)}
function canCraftMaterial(r){let freed=dev.materials?0:Object.values(r.materials).reduce((a,b)=>a+b,0);return materialCraftMax(r)>0&&cargoUsed()-freed+1<=cargoCapacity()}
function menuAvailable(name){
 if(name==='upgrades')return (dev.allRecipes?upgradeOffers():upgradeBatch()).some(u=>!upgradeHas(u.id)&&upgradeAffordable(u))||s.repairs.some(r=>repairNeeded(r)&&(dev.credits||s.credits>=r.cost));
 if(name==='systems')return Object.keys(SYSTEM_BASE_COST).some(systemCanBuy)||(s.researchLevel===0&&canPayCost(researchSpeedCost()));
 if(name==='research'){if(s.researchLevel<1)return false;if(canPayCost(researchSpeedCost()))return true;let recipes=[...BIOTECH_RECIPES,...(s.researchSlots<32?[slotProject(s.researchSlots+1)]:[])];return researchHasRoom()&&recipes.some(r=>researchEligible(r)&&canPayCost(researchRequirements(r)))}
 if(name==='crafting')return craftingBatch().some(craftingRecipeAffordable);
 if(name==='prestige')return universeReward()>0||(s.universe>1||dev.aether)&&UNIVERSE_UPGRADES.some(u=>dev.aether||s.spaceGems>=universePrice(u.key));return false
}

function menuUnlocked(name){return name==='research'?s.researchLevel>0:name==='prestige'?!!s.universeUnlocked:true}
function refreshMenuIndicators(){if(s.planet>=3||s.universe>1)s.universeUnlocked=1;if(!menuUnlocked(tab))tab='weapons';let visible=0;document.querySelectorAll('[data-tab]').forEach(b=>{b.hidden=!menuUnlocked(b.dataset.tab);if(!b.hidden)visible++;let active=tab===b.dataset.tab;b.classList.toggle('active',active);b.classList.toggle('available',menuAvailable(b.dataset.tab));b.setAttribute('aria-pressed',String(active))});document.querySelector('.tabs').style.gridTemplateColumns='repeat('+Math.max(1,visible)+',minmax(0,1fr))'}
function selectMenu(name){if(!menuUnlocked(name))return;setInfoCollapsed(false);infoSystem=-1;tab=tab===name?'weapons':name;renderPanel()}
const SYSTEM_BASE_COST={oreScanner:75,plantScanner:350,creatureScanner:600,alienScanner:3000,geology:100,navigation:300,targeting:200,engine:100,reactor:250,shield:200,hull:175,cargo:125,salvage:225};
const SYSTEM_RECIPES={
 oreScanner:{'Silver':25,'Copper':40},
 plantScanner:{'Copper':30,'Quartz':6},
 creatureScanner:{'Silver':25,'Copper':25},
 alienScanner:{'Copper':50,'Quartz':10},
 geology:{'Silver':20,'Copper':15,'Ancient Relay Fragment':1},
 navigation:{'Copper':35,'Quartz':6,'Ancient Relay Fragment':1},
 targeting:{'Silver':20,'Copper':25},
 engine:{'Silver':40,'Copper':30,'Dormant Alien Circuit':1},
 reactor:{'Silver':50,'Copper':60,'Alien conductor':1,'Dormant Alien Circuit':1},
 shield:{'Copper':55,'Quartz':8,'Dormant Alien Circuit':1,'Alien conductor':1},
 hull:{'Silver':60,'Copper':20,'Alien conductor':1},
 cargo:{'Silver':50,'Copper':25,'Ancient Relay Fragment':1},
 salvage:{'Silver':35,'Copper':25,'Alien conductor':1}
};

function systemRecipe(key){return tierMaterials(originalsystemRecipe(key),1+TECH_PLATEAUS.filter(n=>s[key]+1>=n).length)}
const TECH_PLATEAUS=[10,25,50,75,100,150,200,250,300,400,500];
function originalsystemRecipe(key){if(key==='targeting'&&s[key]===0)return {'Silver':20,'Copper':25};if(Object.values(SCANNER_KEYS).includes(key)&&s[key]===0)return {};let recipe={...SYSTEM_RECIPES[key]},level=s[key],stage=TECH_PLATEAUS.filter(n=>level+1>=n).length,tech=['Dormant Alien Circuit','Bio-Neural Matrix','Graviton Lens','Quantum Memory Core','Phase Lattice','Singularity Seed'];for(let i=0;i<Math.min(stage,tech.length);i++)recipe[tech[i]]=1+Math.floor(Math.max(0,stage-i-1)/2);return Object.fromEntries(Object.entries(recipe).map(([name,n])=>[name,TECH_ITEMS.some(t=>t[0]===name)?n:Math.ceil(n*(1+level*.12))]))}

function systemCanBuy(key){return (dev.credits||s.credits>=systemCost(key))&&Object.entries(systemRecipe(key)).every(([name,n])=>(dev.materials||craftOwned(name)>=n))}
function systemMaterialsMarkup(key){let recipe=Object.entries(systemRecipe(key));return recipe.length?'<div class="system-materials">'+recipe.map(([name,n])=>`<span class="${(dev.materials||craftOwned(name)>=n)?'enough':'missing'}">${name} ${dev.materials?'∞':fmt(s.inventory[name]||0)}/${fmt(n)}</span>`).join(' · ')+'</div>':''}
function systemCost(key){return Math.ceil(SYSTEM_BASE_COST[key]*1.4**s[key])}
function cargoUsed(){return Object.entries(s.inventory).reduce((n,[name,amount])=>n+(MERCHANT_RELICS.some(base=>name===base||name.includes(' '+base+' · U'))?0:amount),0)}
function cargoCapacity(){return Math.floor(bioFactor('cargo')*(1200+600*s.cargo+(upgradeHas('cargo-racks')?400:0))*(upgradeHas('cargo-compression')?1.25:1))+(upgradeHas('cargo-expanded')?1000:0)+shipUpgradeBonus('hold',[300,500,800])+(equipped('cargo-web')?500:0)+(equipped('fold-vault')?5000:0)+200*universeLevel('cargo')}
function storeCargo(name,amount){let g=EQUIPMENT.find(g=>name==='Equipment: '+g.name);if(g){let n=Math.max(0,Math.floor(amount));s.equipmentInventory[g.id]=(s.equipmentInventory[g.id]||0)+n;return n}let n=Math.min(Math.max(0,Math.floor(amount)),Math.max(0,cargoCapacity()-cargoUsed()));if(n)s.inventory[name]=(s.inventory[name]||0)+n;return n}
function systemEffectRows(key){let level=s[key];switch(key){
 case 'geology':return [['Planet class',level?planetClass().name:'Purchase to survey'],['Mean block HP',level>=2?fmt(cells.reduce((n,c)=>n+c.max,0)/cells.length):'Unlock at level 2'],['Deposit count',level>=3?discoveries.length:'Unlock at level 3'],['Deepest deposit',level>=4?Math.max(...discoveries.map(d=>Math.floor(planetRadius()-Math.hypot(d.x+.5,d.y+.5))))+' blocks':'Unlock at level 4']];
 case 'navigation':return [['Wreck discovery chance',Math.min(75,level*10)+'% per planet']];
 case 'targeting':return [['Damage efficiency','+'+level*3+'%'],['Target preference','Forward blocks; stronger at higher levels']];
 case 'reactor':return [['Weapon damage','+'+level*8+'%']];
 case 'shield':return [['Retaliation reduction',Math.round((1-1/(1+level*.3))*100)+'%']];
 case 'hull':return [['Retaliation reduction',Math.round((1-1/(1+level*.2))*100)+'%'],['Equipment resistance','Weapon-level loss chance falls with each level']];
 case 'cargo':return [['Cargo capacity',fmt(cargoCapacity())],['Cargo used',fmt(cargoUsed())],['Protected cargo',Math.min(80,level*10)+'%']];
 case 'salvage':return [['Wreck and merchant loot','+'+level*20+'%']];
 case 'oreScanner':return [['Rock credit bonus','+'+level*5+'%']];
 default:return [];
}}
let encounter=null,encounterQueue=[];
if(Array.isArray(s.grid?.encounters)){let valid=s.grid.encounters.filter(x=>x&&['merchant','wreck','asteroid'].includes(x.type)).slice(0,4);encounter=valid.shift()||null;encounterQueue=valid;for(let e of [encounter,...encounterQueue])if(e?.type==='wreck'){e.type='merchant';e.alien=true}}
const MERCHANT_PRICES={'Silver':3,'Copper':4,'Quartz':8,'Emerald':30,'Sapphire':40,'Titanium':15,'Hardened alloy':25,'Navigation tech':45,'Ancient Relay Fragment':80,'Alien conductor':65,'Dormant Alien Circuit':90,'Bio-Neural Matrix':150,'Graviton Lens':150,'Phase Lattice':250,'Quantum Memory Core':250,'Singularity Seed':500};
RESOURCE_TIERS.forEach((row,tier)=>row.forEach((name,i)=>MERCHANT_PRICES[name]=[4,12,30,65][tier]*(i<2?1:3)));
const MERCHANT_RELICS=['Corsair Power Coupler','Smuggler Shield Matrix','Void Cargo Seal'];
function htmlSafe(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}


function merchantHpRatio(m){return m.blocks.reduce((n,b)=>n+Math.max(0,b.hp),0)/m.blocks.reduce((n,b)=>n+b.max,0)}
function merchantStructure(m){return 1+(m.structureMax-1)*Math.max(0,m.integrity??1)}
function absorbShield(p,damage){let absorbed=Math.min(p.shield||0,damage);p.shield=Math.max(0,(p.shield||0)-absorbed);return damage-absorbed}
function combatPercent(now,max){return max>0?Math.max(0,Math.min(100,Math.ceil(now/max*100))):0}
function merchantFleetSize(){return 1+Math.floor(Math.max(0,s.merchantVisits-1)/8)}
function merchantPlateau(){return Math.floor(Math.max(0,s.merchantVisits-1)/8)}
function prepareMerchant(){if(!encounter||encounter.type!=='merchant')return;let e=encounter;if(!Number.isFinite(e.priceScale))e.priceScale=merchantProgressScale();if(e.version===3){ensureAlienCombat(e);if(e.hullSchema!==5){e.style=Math.max(0,Math.min(24,e.style||0));for(let m of e.ships){let max=m.blocks.reduce((n,b)=>n+b.max,0),hp=m.blocks.reduce((n,b)=>n+Math.max(0,b.hp),0);m.style=e.style;m.blocks=alienHullBlocks(m.style,max);for(let b of m.blocks)b.hp=b.max*(hp/(max||1))}e.hullSchema=5}ensureMerchantPlans();return}
 if(!Number.isInteger(e.style))e.style=Math.floor(Math.random()*ALIEN_HULLS.length);if(!e.alien)establishMerchantBaseline();if(e.version!==2&&!e.alien)s.merchantVisits++;let fleet=e.alien?1:merchantFleetSize(),tier=e.alien?0:merchantPlateau();e.version=3;e.phase='choice';e.elapsed=0;e.returnCamera={...camera};e.player={x:0,y:6,a:-Math.PI/2,hp:(playerHullMax())*(dev.hp?1:s.hullCondition),max:playerHullMax(),shield:playerShieldMax()*s.shieldCondition,shieldMax:playerShieldMax()};e.fired=Array(10).fill(-100);e.shots=[];e.effects=[];e.kills=0;e.rewards=[];e.selected='Silver';e.quantity=1;e.stock={};for(const [name,price] of Object.entries(MERCHANT_PRICES))e.stock[name]=name.includes('Fragment')||name.includes('Circuit')?2+tier:Math.ceil((price<10?160:price<40?25:8)*(1+tier*.5));
 for(const [name,rarity] of TECH_ITEMS)if(rarity>Math.min(4,1+tier))e.stock[name]=0;e.stock['Hardened alloy']=0;
 ensureMerchantPlans();e.ships=Array.from({length:fleet},(_,i)=>{let hp=s.merchantBaseHp/18*2**tier;return {shield:0,shieldMax:0,integrity:1,structureMax:1,x:(i-(fleet-1)/2)*8,y:-3,a:Math.PI/2,lastShot:-1,blocks:[1,1,3,3,5,5].flatMap((width,row)=>Array.from({length:width},(_,col)=>({x:(col-(width-1)/2)*.8,y:(row-2.5)*.8,hp,max:hp})))}});if(e.alien){e.enemyDamage=Math.max(3,(playerHullMax()+playerShieldMax())*.07);e.enemyShotSpeed=Math.max(8,shipSpeed()*2);e.phase='wreckChoice';e.salvageProgress=0;e.ambush=Math.random()<.3;e.ambushAt=3+Math.random()*5;let dps=WEAPONS.reduce((n,w,i)=>n+(weaponOn(i)?weaponDps(i):0),0);for(let m of e.ships){m.shieldMax=m.shield=0;m.structureMax=1;for(let b of m.blocks)b.hp=b.max=Math.max(8,dps*12/18)}}e.hullSchema=5;for(let m of e.ships){m.style=e.style;let hp=m.blocks.reduce((n,b)=>n+b.max,0);m.blocks=alienHullBlocks(e.style,hp)}ensureAlienCombat(e);e.player.x=ship.x;e.player.y=ship.y;e.player.a=ship.a;e.inPlace=true;for(let [i,m] of e.ships.entries()){m.x=ship.x+12+i*4;m.y=ship.y-6}merchantSound('arrival');save();renderUI();
}
function merchantProgressScale(){return Math.max(1,Math.pow(1.28,Math.max(0,s.planet-2))*(1+Math.max(0,s.universe-1)*.15)*mult()*(1+Math.max(0,s.drill-1)*.035))}
function merchantPriceScale(){if(encounter?.type==='merchant'){if(!Number.isFinite(encounter.priceScale))encounter.priceScale=merchantProgressScale();return encounter.priceScale}return merchantProgressScale()}
function merchantItemPrice(name){return Math.ceil(baseMerchantItemPrice(name)*merchantPriceScale()*(name.startsWith('Equipment: ')?25:5))}
function merchantPlanPrice(recipe){return Math.ceil(recipe.planCost*merchantPriceScale()*10)}
function baseMerchantItemPrice(name){if(name==='Antiviral Serum')return 300;let equipment=EQUIPMENT.find(g=>name==='Equipment: '+g.name);if(equipment)return equipment.price;if(name.endsWith(' bio info')){let species=LIFE_SPECIES.find(x=>name===x[0]+' bio info'||name.includes(' '+x[0]+' · U'));return 30*(species?.[1]||1)**2}return MERCHANT_PRICES[name]||Math.max(10,TECH_ITEMS.some(x=>x[0]===name)?50:15)}
function tradeLimit(side){let e=encounter;if(!e||e.phase!=='trade')return 0;let name=e.selected,price=merchantItemPrice(name);return side==='buy'?Math.max(0,Math.min(e.stock[name]||0,EQUIPMENT.some(g=>name==='Equipment: '+g.name)?Infinity:Math.floor(cargoCapacity()-cargoUsed()),dev.credits?Infinity:Math.floor(s.credits/price))):Math.max(0,playerTradeOwned(name))}
function tradeQuantity(side){let max=tradeLimit(side);return Math.min(max,encounter.quantity==='max'?max:Number(encounter.quantity)||1)}
function tradeNames(){let names=[...new Set([...Object.keys(encounter.stock),...Object.keys(s.inventory),...EQUIPMENT.filter(g=>(s.equipmentInventory[g.id]||0)>0).map(g=>'Equipment: '+g.name)])];return names.filter(name=>!MERCHANT_RELICS.includes(name)&&((encounter.stock[name]||0)>0||playerTradeOwned(name)>0)).sort((a,b)=>tradeType(a).localeCompare(tradeType(b))||a.localeCompare(b))}
function tradeType(name){if(name.startsWith('Equipment: '))return 'Equipment';if(name.endsWith(' bio info'))return 'Bio information';if(TECH_ITEMS.some(t=>t[0]===name)||name==='Navigation tech')return 'Alien tech';if(RESOURCE_TIERS.some(t=>t.slice(0,2).includes(name)))return 'Ores';if(RESOURCE_TIERS.some(t=>t.slice(2).includes(name)))return 'Gems';if(['Lumen Spore','Frostveil Lichen','Copperroot Mycelium','Voidlace Polyp','Starwhisper Orchid'].some(base=>name===base||name.includes(' '+base+' · U')))return 'Plants';return 'Materials'}
function tradeCard(){let e=encounter,names=tradeNames(),name=e.selected;let list=side=>{let html='',group='';names.forEach((item,i)=>{let n=side==='merchant'?e.stock[item]||0:playerTradeOwned(item);if(n<=0)return;let type=tradeType(item);if(type!==group){group=type;html+=`<div class="trade-heading">${type}</div>`}html+=`<button class="trade-item ${item===name?'selected':''}" data-action="merchant:item:${i}"><span>${htmlSafe(item.replace(/^Equipment: /,''))}</span><b>${fmt(n)}</b></button>`});return html};return `<div class="weapon-choice-backdrop"><section class="weapon-choice trade-card" role="dialog" aria-modal="true" aria-label="Merchant trading"><div class="row"><div class="title">TRADE · ${fmt(s.credits)} CR</div><button class="choice-close" data-action="merchant:closeTrade" aria-label="Close trade">×</button></div><div class="trade-quantity">${[1,10,100,1000,'max'].map(q=>`<button data-action="merchant:quantity:${q}" class="${e.quantity===q?'selected':''}">${String(q).toUpperCase()}</button>`).join('')}</div><div class="trade-layout"><div><div class="trade-heading">MERCHANT</div><div class="trade-items">${list('merchant')}</div></div><div class="trade-actions"><div>${htmlSafe(name)}</div><button class="buy" data-action="merchant:buy" ${tradeQuantity('buy')<1?'disabled':''}>BUY →<small>${fmt(tradeQuantity('buy'))} · ${fmt(tradeQuantity('buy')*merchantItemPrice(name))} CR</small></button><button class="buy" data-action="merchant:sell" ${tradeQuantity('sell')<1?'disabled':''}>← SELL<small>${fmt(tradeQuantity('sell'))} · ${fmt(tradeQuantity('sell')*Math.max(1,Math.floor(merchantItemPrice(name)*.6)))} CR</small></button></div><div><div class="trade-heading">PLAYER</div><div class="trade-items">${list('player')}</div></div></div><div class="desc">Cargo ${fmt(cargoUsed())}/${fmt(cargoCapacity())}</div>${merchantRecipesMarkup()}</section></div>`}
function encounterMarkup(){if(!encounter)return '';if(encounter.type==='wreck')return `<div class="weapon-choice-backdrop"><section class="weapon-choice"><div class="title">WRECK DETECTED</div><button class="buy wide" data-action="encounter:recover">RECOVER SALVAGE</button><button class="buy wide" data-action="encounter:leave">CONTINUE</button></section></div>`;if(encounter.phase==='trade')return tradeCard();if(encounter.phase==='result')return combatReport();return ''}
function devClearPlanet(mode=1){if(encounter||s.devPlanetReady)return;visitor=null;s.devPlanetReady=mode;for(const c of cells)if(c.hp>0)awardBlock(c);planetClearPending=false;lockedTarget=null;resourceTarget=null;bullets=[];drones=[];mortars=[];waves=[];embeddedStars=[];pendingHits=[];effects=[];dust=[];floaters=[];renderUI();save()}
function updateCombatStats(){let root=$('combatStats');if(!encounter||encounter.type!=='merchant'||!encounter.player||encounter.phase==='result'){root.hidden=true;return}root.hidden=false;let e=encounter,p=e.player;let html='<div class="combat-side player"><b>PLAYER</b><span>CREW '+fmt(p.hp)+' / '+fmt(p.max)+'</span><span>SHIELD '+combatPercent(p.shield,p.shieldMax)+'%</span></div><div class="combat-side merchant"><b>ALIEN</b>'+e.ships.map(m=>'<div><span>CREW '+fmt(alienCrew(m))+' / '+fmt(m.crewMax)+'</span><span>ENERGY '+fmt(m.energy)+' / '+fmt(m.energyMax)+'</span><small>'+ALIEN_COMBAT[m.style][0]+' · '+ALIEN_COMBAT[m.style][1]+'</small></div>').join('')+'</div>';if(root.dataset.stats!==html){root.dataset.stats=html;root.innerHTML=html}}

function setMerchantOverlay(root,markup){if(root.dataset.sceneMarkup!==markup){root.dataset.sceneMarkup=markup;root.innerHTML=markup}}
function updateMerchantOverlay(){let retreat=$('merchantRetreat');retreat.hidden=!(encounter?.type==='merchant'&&encounter.phase==='combat');updateCombatStats();let root=$('merchantOverlay');if(s.devPlanetReady){root.hidden=false;setMerchantOverlay(root,'<div>PLANET CLEARED</div><button data-action="devContinue">CONTINUE TO ALIEN SHIP</button>');return}if(!encounter||encounter.type!=='merchant'){if(visitor&&!visitor.arriving&&!visitor.departing&&!visitor.ignored){root.hidden=false;setMerchantOverlay(root,'<div>'+ALIEN_HULLS[visitor.style].name+'</div>'+'<button data-action="visitor:trade">TRADE</button><button data-action="visitor:attack">ATTACK</button><button data-action="visitor:ignore">IGNORE</button>')}else{setMerchantOverlay(root,'');root.hidden=true}return}root.hidden=false;let e=encounter;if(e.alien&&e.phase==='wreckChoice'){setMerchantOverlay(root,'<div class="title">ALIEN DERELICT</div><button data-action="merchant:salvage">SALVAGE</button><button data-action="merchant:leave">PASS</button>')}else if(e.alien&&e.phase==='salvaging'){setMerchantOverlay(root,`<div class="title">SALVAGING</div><div class="milestone-progress"><div style="width:${Math.min(100,e.salvageProgress/10*100)}%"></div></div>`)}else if(e.alien&&e.phase==='salvaged'){setMerchantOverlay(root,`<div class="title">SALVAGE RECOVERED</div><div class="desc">${e.salvage.map(([name,n])=>htmlSafe(name)+' ×'+fmt(n)).join('<br>')}</div><button data-action="merchant:leave">CONTINUE</button>`)}else if(e.phase==='choice'){setMerchantOverlay(root,'<div class="title">ALIEN CONTACT</div><div class="merchant-buttons"><button data-action="merchant:attack">ATTACK</button><button data-action="merchant:trade">TRADE</button><button data-action="merchant:leave">IGNORE</button></div>')}else if(e.phase==='combat'||e.phase==='aftermath'||e.phase==='result'){root.hidden=true;setMerchantOverlay(root,'')}else if(e.phase==='result'){setMerchantOverlay(root,`<div class="title">${e.won?'FLEET DEFEATED':e.departAfterReport?'SHIP DISABLED':'ALIENS WITHDRAW'}</div><div>${htmlSafe(e.result)}</div><button data-action="merchant:leave">CONTINUE</button>`)}else setMerchantOverlay(root,'')}
function encounterLoot(){let available=TECH_ITEMS.filter(t=>t[1]<=Math.min(4,1+merchantPlateau())),tech=available[Math.floor(Math.random()*available.length)],bonus=(1+s.salvage*.2)*(upgradeHas('salvage-sorter')?1.25:1)*(upgradeHas('salvage-reclaimer')?1.25:1)*bioFactor('salvage')*universeFactor('salvage',.08),grants={'Silver':Math.ceil(12*bonus),'Navigation tech':limitedTechQuantity(bonus),'Alien conductor':limitedTechQuantity(bonus),'Ancient Relay Fragment':limitedTechQuantity(bonus)};grants[tech[0]]=limitedTechQuantity((grants[tech[0]]||0)+1);return Object.entries(grants).reduce((total,[name,n])=>total+storeCargo(name,n),0)}

let combatRecovery=s.grid?.combatRecovery||false;
function combatClearance(p){let best=Infinity;for(let c of cells)if(c.hp>0)best=Math.min(best,Math.hypot(Math.max(0,Math.abs(p.x-c.x-.5)-.5),Math.max(0,Math.abs(p.y-c.y-.5)-.5)));return best}
function combatExitPoint(p){let best=null,cost=Infinity;for(let i=0;i<48;i++){let a=i*TAU/48,r=planetRadius()+6,q={x:Math.cos(a)*r,y:Math.sin(a)*r};if(combatClearance(q)<3)continue;let d=Math.hypot(q.x-p.x,q.y-p.y);if(d<cost){best=q;cost=d}}return best||{x:p.x+planetRadius()*2+10,y:p.y}}
function stepCombatRecovery(dt){if(!combatRecovery)return false;if(combatClearance(ship)>=3){combatRecovery=false;resumeMiningFlight();notice('MINING RESUMED');save();return false}let q=ship.combatExit||(ship.combatExit=combatExitPoint(ship));moveCombatShip(ship,q.x,q.y,shipSpeed(),turnRate(),dt);if(followShip){camera.x+=(ship.x-camera.x)*Math.min(1,dt*2);camera.y+=(ship.y-camera.y)*Math.min(1,dt*2)}draw(simulationTime,true);let scale=mapScale();drawRecoveryShip(scale);return true}
function drawRecoveryShip(scale){ctx.save();ctx.translate(cv.clientWidth/2+(ship.x-camera.x)*scale,cv.clientHeight*.38+(ship.y-camera.y)*scale);ctx.rotate(ship.a+Math.PI/2);drawPlayerThrusters(scale*PLAYER_HULL_SIZE,ship,simulationTime);drawShipHull(scale*PLAYER_HULL_SIZE,'player',ship.a);ctx.restore()}
function resumeMiningFlight(){
 // Mining cruises at its configured speed. Combat's braking and status effects end here.
 let vx=Number.isFinite(ship.vx)?ship.vx:0,vy=Number.isFinite(ship.vy)?ship.vy:0,length=Math.hypot(vx,vy),speed=shipSpeed();
 let direction=length>.05?Math.atan2(vy,vx):ship.a;
 ship.vx=Math.cos(direction)*speed;ship.vy=Math.sin(direction)*speed;
 delete ship.limpets;delete ship.confusedUntil;delete ship.combatExit;
 let clear=surfaceClearance(),x=clear.x,y=clear.y,n=Math.hypot(x,y);
 if(Number.isFinite(n)&&n>.001){navNormal.x=x/n;navNormal.y=y/n;let tangent=-navNormal.y*ship.vx+navNormal.x*ship.vy;if(Math.abs(tangent)>.01)orbitDirection=tangent>0?1:-1}
 turnState=null;lockedTarget=null;lastBlock=null;nextAboutFace=simulationTime+12000;
}
function closeEncounter(){let e=encounter;if(e?.type==='asteroid')restoreAsteroidWorld();if(e?.player){ship.x=e.player.x;ship.y=e.player.y;ship.a=e.player.a;ship.vx=e.player.vx||0;ship.vy=e.player.vy||0;ship.thrust=e.player.thrust||0;lockedTarget=null;if(e.phase==='result'&&combatClearance(ship)<3){combatRecovery=true;notice('CLEARING THE SURFACE')}}if(e?.returnCamera&&!e.inPlace){camera.x=e.returnCamera.x;camera.y=e.returnCamera.y}encounter=encounterQueue.shift()||null;if(e?.player&&!encounter&&!combatRecovery)resumeMiningFlight();prepareMerchant();renderUI();save()}

function encounterAction(action){if(!encounter)return;if(action==='leave')closeEncounter();else if(action==='recover'&&encounter.type==='wreck'){notice('WRECK SALVAGED · '+encounterLoot()+' ITEMS');closeEncounter()}}
function merchantAction(action){if(!encounter||encounter.type!=='merchant')return;prepareMerchant();let e=encounter,[kind,value]=action.split(':');if(kind==='leave'&&e.phase==='result'){e.reportDismissed=true;infoWeapon=-1;infoSystem=-1;weaponChoiceOpen=false}
 if(kind==='leave'&&e.phase==='result'&&e.departAfterReport){e.departAfterReport=false;e.report=null;e.phase='aftermath';e.ending={won:false,retreat:false,age:0,reportShown:true};for(let m of e.ships){m.untargetable=true;let angle=Math.atan2(m.y-e.player.y,m.x-e.player.x);m.exitX=m.x+Math.cos(angle)*200;m.exitY=m.y+Math.sin(angle)*200}renderUI();save();return}if(kind==='leave'&&['choice','result','wreckChoice','salvaged'].includes(e.phase)){closeEncounter();return}
 if(kind==='salvage'&&e.alien&&e.phase==='wreckChoice'){e.phase='salvaging';e.salvageProgress=0}
 else if(kind==='attack'&&e.phase==='choice'){e.phase='combat';merchantSound('battle');e.elapsed=0;e.startHp=e.player.hp;e.startShield=e.player.shield}
 else if(kind==='trade'&&e.phase==='choice'){e.phase='trade';merchantSound('trade')}
 else if(kind==='closeTrade'&&e.phase==='trade')e.phase='choice';
 else if(kind==='retreat'&&e.phase==='combat')finishMerchantCombat(false,true);
 else if(e.phase==='trade'){
 if(kind==='item'){let names=tradeNames(),i=Number(value);if(Number.isInteger(i)&&names[i])e.selected=names[i]}
 if(kind==='quantity'&&['1','10','100','1000','max'].includes(value))e.quantity=value==='max'?'max':Number(value);
 if(kind==='buy'){let n=tradeQuantity('buy');if(n>0){merchantSound('buy');let price=n*merchantItemPrice(e.selected);if(!dev.credits)s.credits-=price;e.stock[e.selected]-=n;storeCargo(e.selected,n)}}
 if(kind==='sell'){let n=tradeQuantity('sell');if(n>0){merchantSound('sell');takeTradeItem(e.selected,n);e.stock[e.selected]=(e.stock[e.selected]||0)+n;gain(n*Math.max(1,Math.floor(merchantItemPrice(e.selected)*.6)))}}
 }renderUI();save();
}
function merchantBlockPosition(m,b){let a=m.a+Math.PI/2;return {x:m.x+b.x*Math.cos(a)-b.y*Math.sin(a),y:m.y+b.x*Math.sin(a)+b.y*Math.cos(a)}}
function merchantBlocks(){return encounter.ships.flatMap(m=>m.blocks.filter(b=>b.hp>0).map(b=>({m,b,...merchantBlockPosition(m,b)})))}


function repairOriginalCost(type,key,level){if(type==='weapon')return Math.ceil(25*(Number(key)+1)*1.12**Math.max(0,level-2));if(type==='upgrade')return Math.ceil(12*1.48**Math.max(0,level-2));let old=s[key];s[key]=Math.max(0,level-1);let price=systemCost(key)+Object.entries(systemRecipe(key)).reduce((n,[name,quantity])=>n+merchantItemPrice(name)*quantity,0);s[key]=old;return price}
function addRepair(type,key,name,from,to,original){if(type==='hull'||type==='shield'){let old=s.repairs.find(r=>r.type===type);if(old)return old}let item={id:s.repairSerial++,type,key,name,from,to,original:Math.ceil(original),cost:Math.ceil(original*.25)};s.repairs.push(item);return item}
function repairNeeded(r){if(r.type==='hull')return s.hullCondition<1;if(r.type==='shield')return s.shieldCondition<1;if(r.type==='weapon')return s.weaponLevels[Number(r.key)]<r.from;return s[r.key]<r.from}
function repairMarkup(inline=false){let pending=s.repairs.filter(repairNeeded);if(!pending.length)return '';let total=pending.reduce((n,r)=>n+r.cost,0);return '<div class="'+(inline?'combat-repairs':'card')+'"><div class="title">REPAIRS</div><div class="desc">Repairs cost 25% of original value.</div>'+pending.map(r=>`<div class="ingredient"><span>${htmlSafe(r.name)} ${r.type==='hull'||r.type==='shield'?'':r.from+' → '+r.to}</span><button class="buy" data-action="repair:${r.id}" ${!dev.credits&&s.credits<r.cost?'disabled':''}>${fmt(r.cost)} CR</button></div>`).join('')+`<button class="buy wide" data-action="repair:all" ${!dev.credits&&s.credits<total?'disabled':''}>${inline?'REPAIR & CONTINUE':'REPAIR ALL'} · ${fmt(total)} CR</button></div>`}
function repairAction(value){let chosen=s.repairs.filter(r=>repairNeeded(r)&&(value==='all'||String(r.id)===value)),total=chosen.reduce((n,r)=>n+r.cost,0);if(!chosen.length||(!dev.credits&&s.credits<total))return;if(!dev.credits)s.credits-=total;for(let r of chosen){if(r.type==='hull')s.hullCondition=1;else if(r.type==='shield')s.shieldCondition=1;else if(r.type==='weapon')s.weaponLevels[Number(r.key)]=Math.max(s.weaponLevels[Number(r.key)],r.from);else s[r.key]=Math.max(s[r.key],r.from)}s.repairs=s.repairs.filter(repairNeeded);if(encounter?.player){encounter.player.hp=encounter.player.max*s.hullCondition;encounter.player.shield=encounter.player.shieldMax*s.shieldCondition}if(encounter?.phase==='result'&&encounter.report&&!s.repairs.some(repairNeeded)){merchantAction('leave');return}renderUI();save()}
function renderCombatReportDialog(){let root=$('combatReportDialog');if(!root){root=document.createElement('div');root.id='combatReportDialog';document.body.appendChild(root);root.addEventListener('click',e=>{let button=e.target.closest('[data-action]');if(button){e.stopPropagation();purchase(button.dataset.action)}})}let dialog=root.querySelector('.weapon-choice'),scroll=dialog?.scrollTop||0;root.innerHTML=encounter?.phase==='result'?combatReport():'';dialog=root.querySelector('.weapon-choice');if(dialog)dialog.scrollTop=scroll}
function combatReport(){let e=encounter;if(!e?.report||e.reportDismissed)return '';let r=e.report;return `<div class="weapon-choice-backdrop"><section class="weapon-choice" role="dialog" aria-modal="true" aria-label="Combat damage report"><div class="title">${e.won?'VICTORY':e.departAfterReport?'CREW DEPLETED · SHIP DISABLED':'COMBAT DAMAGE REPORT'}</div><dl class="stats-list"><div><dt>Crew lost</dt><dd>${r.hull}%</dd></div><div><dt>Shield depleted</dt><dd>${r.shield}%</dd></div><div><dt>Credits lost</dt><dd>${fmt(r.credits)} CR</dd></div></dl><div class="title">Lost cargo</div><div class="desc">${r.cargo.length?r.cargo.map(([name,n])=>htmlSafe(name)+' ×'+fmt(n)).join('<br>'):'No cargo aboard.'}</div><div class="title">Damaged equipment and tech</div><div class="desc">${r.damage.length?r.damage.map(x=>htmlSafe(x)).join('<br>'):'No equipment lost.'}</div><div class="title">Recovered salvage</div><div class="desc">${r.salvage?.length?r.salvage.map(([name,n])=>htmlSafe(name)+' ×'+fmt(n)).join('<br>'):'No salvage recovered.'}</div>${repairMarkup(true)}<button class="buy wide" data-action="merchant:leave">${s.repairs.some(repairNeeded)?'CONTINUE WITHOUT FURTHER REPAIRS':'CONTINUE'}</button></section></div>`}
function completeMerchantCombat(won,retreat=false){let e=encounter;if(e.phase!=='combat')return;merchantSound(won?'victory':retreat?'retreat':'defeat');e.phase='result';e.won=won;e.shots=[];let severity=Math.max(0,((e.startHp??e.player.max)-e.player.hp)/e.player.max),report={hull:Math.round(((e.startHp??e.player.max)-e.player.hp)/e.player.max*100),shield:e.player.shieldMax?Math.round(((e.startShield??e.player.shieldMax)-e.player.shield)/e.player.shieldMax*100):0,cargo:[],damage:[],credits:0};
 let combatHullDamage=Math.max(0,((e.startHp??e.player.max)-e.player.hp)/e.player.max),cargoLossRate=won?Math.min(.35,combatHullDamage*.35):retreat?Math.min(.5,.1+combatHullDamage*.4):Math.min(.8,.25+combatHullDamage*.55);cargoLossRate/=1+s.cargo*.1;for(let [name,n] of Object.entries(s.inventory))if(n>0&&!MERCHANT_RELICS.includes(name)){let lost=Math.floor(n*cargoLossRate);if(lost){report.cargo.push([name,lost]);s.inventory[name]-=lost}}
 s.hullCondition=Math.max(.1,e.player.hp/e.player.max);s.shieldCondition=e.player.shieldMax?e.player.shield/e.player.shieldMax:1;
 if(s.hullCondition<1)addRepair('hull','hullCondition','Crew quarters',1,0,100+SYSTEM_BASE_COST.hull*s.hull);
 if(s.shieldCondition<1)addRepair('shield','shieldCondition','Shield hardware',1,0,SYSTEM_BASE_COST.shield*Math.max(1,s.shield));
 if(severity>.25){let candidates=Object.keys(SYSTEM_BASE_COST).filter(key=>s[key]>0),count=Math.min(candidates.length,severity>.8&&!retreat?2:1);for(let i=0;i<count;i++){let index=Math.floor(Math.random()*candidates.length),key=candidates.splice(index,1)[0],from=s[key],name=SHIP_SYSTEMS.find(x=>x[3]===key)[0],original=repairOriginalCost('system',key,from);s[key]--;addRepair('system',key,name,from,s[key],original);report.damage.push(name+' level '+from+' → '+s[key])}
 let options=s.weaponLevels.map((level,i)=>i).filter(i=>weaponOn(i)&&s.weaponLevels[i]>1);if(options.length&&severity>.5&&!retreat){let key=options[Math.floor(Math.random()*options.length)],from=s.weaponLevels[key];s.weaponLevels[key]--;addRepair('weapon',String(key),WEAPONS[key][0],from,from-1,repairOriginalCost('weapon',key,from));report.damage.push(WEAPONS[key][0]+' level '+from+' → '+(from-1))}
 if(s.drill>1&&severity>.8&&!retreat){let from=s.drill;s.drill--;addRepair('upgrade','drill','Drill power',from,from-1,repairOriginalCost('upgrade','drill',from));report.damage.push('Drill power level '+from+' → '+(from-1))}}
 if(!won){let loss=(retreat?.08:.2)/((1+s.shield*.3)*(1+s.hull*.2));report.credits=Math.ceil(s.credits*loss);s.credits=Math.max(0,s.credits-report.credits)}
 report.salvage=[];let beforeSalvage={...s.inventory};e.report=report;e.result=won?'Ship salvage recovered. Check the damage report.':'Combat complete. Review damage and salvage.';if(e.kills)for(let i=0;i<e.kills;i++){storeCargo('Silver',3);storeCargo('Alien conductor',1);storeCargo('Navigation tech',1)}report.salvage=Object.entries(s.inventory).map(([name,n])=>[name,n-(beforeSalvage[name]||0)]).filter(([name,n])=>n>0);for(const reward of e.rewards) {let gear=EQUIPMENT.find(g=>reward==='Equipment: '+g.name),name=gear?reward+' ('+gear.effect+')':reward;let item=report.salvage.find(x=>x[0]===name);if(item)item[1]++;else report.salvage.push([name,1])}renderUI();save()
}
// Alien velocity changes only through forward thrust. Turning preserves momentum.
function flyInertialessAlien(p,wantX,wantY,speed,turn,dt){let moving=Math.hypot(wantX,wantY)>.08,bearing=moving?Math.atan2(wantY,wantX):p.a,delta=Math.atan2(Math.sin(bearing-p.a),Math.cos(bearing-p.a));p.steering=Math.max(-1,Math.min(1,delta));p.a+=Math.max(-turn*dt,Math.min(turn*dt,delta));p.thrust=moving&&Math.cos(bearing-p.a)>.97?1:0;p.vx=p.thrust?Math.cos(p.a)*speed:0;p.vy=p.thrust?Math.sin(p.a)*speed:0;p.x+=p.vx*dt;p.y+=p.vy*dt}
// Source: uqm/ship.c inertial_thrust. Gravity wells are not active in Orbit Forge combat.
function sourceThrust(p,maxSpeed,increment){
 let vx=p.vx||0,vy=p.vy||0,current=vx*vx+vy*vy,cap=maxSpeed*maxSpeed;
 if(Math.abs(increment-maxSpeed)<1e-9){p.vx=Math.cos(p.a)*maxSpeed;p.vy=Math.sin(p.a)*maxSpeed;return;}
 let dx=vx+Math.cos(p.a)*increment,dy=vy+Math.sin(p.a)*increment,desired=dx*dx+dy*dy;
 if(desired<=cap||desired<current){p.vx=dx;p.vy=dy;return;}
 let travel=Math.atan2(vy,vx),aligned=Math.abs(Math.atan2(Math.sin(travel-p.a),Math.cos(travel-p.a)))<1e-6;
 if(aligned){if(current<=cap){p.vx=Math.cos(p.a)*maxSpeed;p.vy=Math.sin(p.a)*maxSpeed;}return;}
 dx=vx+Math.cos(p.a)*increment*.5-Math.cos(travel)*increment;
 dy=vy+Math.sin(p.a)*increment*.5-Math.sin(travel)*increment;
 desired=dx*dx+dy*dy;if(desired<=cap||desired<current){p.vx=dx;p.vy=dy;}
}
function flySourceAlien(p,wantX,wantY,speed,turn,dt){
 let motion=alienMotion(p.style,p),cfg=ALIEN_SOURCE[p.style];
 p.vx=Number.isFinite(p.vx)?p.vx:0;p.vy=Number.isFinite(p.vy)?p.vy:0;
 p.sourceClock??=0;p.sourceThrustWait??=0;
 let remaining=dt;
 while(remaining>1e-9){
  let dx=wantX-p.vx,dy=wantY-p.vy,error=Math.hypot(dx,dy),bearing=error>.08?Math.atan2(dy,dx):p.a;
  // Probe preprocess: it always travels at top speed; a thrust press reverses its facing.
  if(p.style===2){bearing=Math.atan2(wantY,wantX);let behind=Math.cos(bearing-p.a)<0;
   if(behind&&!p.probeReverseHeld)p.a+=Math.PI;p.probeReverseHeld=behind;}
  let slice=Math.min(remaining,1/24-p.sourceClock),delta=Math.atan2(Math.sin(bearing-p.a),Math.cos(bearing-p.a));
  p.steering=Math.sign(delta);p.a+=Math.max(-turn*slice,Math.min(turn*slice,delta));
  let thrust=p.style===2||error>.08&&Math.cos(bearing-p.a)>.97;p.thrust=thrust?1:0;
  // Update thrust at the source's 24 Hz clock; turning alone does not alter momentum.
  if(p.sourceClock<1e-9){
   if(p.sourceThrustWait>0)p.sourceThrustWait--;
   else if(thrust){let wait=cfg.thrustWait;
    if(p.style===13&&p.fastForm)wait=0;
    if(p.style===15&&p.blazerUntil>(encounter?.elapsed??Infinity))wait=0;
    if(p.style===2){p.vx=Math.cos(p.a)*speed;p.vy=Math.sin(p.a)*speed;}
    else sourceThrust(p,speed,motion.acceleration*(wait+1)/24);
    p.sourceThrustWait=wait;
   }
  }
  p.x+=p.vx*slice;p.y+=p.vy*slice;p.sourceClock+=slice;remaining-=slice;
  if(p.sourceClock>=1/24-1e-9)p.sourceClock=0;
 }
}

function flyAlien(p,wantX,wantY,speed,turn,dt,aim=null){
 if(Number.isInteger(p.style)&&p.style!==23&&p!==ship&&p!==encounter?.player){flySourceAlien(p,wantX,wantY,speed,turn,dt);return;}
 if(p.style===23&&p!==ship&&p!==encounter?.player){flyInertialessAlien(p,wantX,wantY,speed,turn,dt);return}
 p.vx=Number.isFinite(p.vx)?p.vx:0;p.vy=Number.isFinite(p.vy)?p.vy:0;
 // Correct the entire velocity vector, including sideways drift, using forward thrust only.
 let dx=wantX-p.vx,dy=wantY-p.vy,error=Math.hypot(dx,dy);
 let bearing=error>.08?Math.atan2(dy,dx):Math.hypot(wantX,wantY)>.08?Math.atan2(wantY,wantX):p.a;
 let delta=Math.atan2(Math.sin(bearing-p.a),Math.cos(bearing-p.a));
 p.steering=Math.max(-1,Math.min(1,delta));p.a+=Math.max(-turn*dt,Math.min(turn*dt,delta));
 let isAlien=Number.isInteger(p.style)&&p!==ship&&p!==encounter?.player,acceleration=isAlien?alienMotion(p.style,p).acceleration:Math.max(.2,speed*2.6),alignment=Math.cos(bearing-p.a);
 p.thrust=error>.08&&alignment>.97?Math.min(1,error/(acceleration*.3)):0;
 p.vx+=Math.cos(p.a)*acceleration*p.thrust*dt;p.vy+=Math.sin(p.a)*acceleration*p.thrust*dt;
 if(isAlien){let velocity=Math.hypot(p.vx,p.vy);if(velocity>speed){p.vx*=speed/velocity;p.vy*=speed/velocity;}}
 p.x+=p.vx*dt;p.y+=p.vy*dt;
}

function moveAlienTo(p,tx,ty,speed,turn,dt){let dx=tx-p.x,dy=ty-p.y,d=Math.hypot(dx,dy),cruise=Math.min(speed,d*.45);flyAlien(p,d?dx/d*cruise:0,d?dy/d*cruise:0,speed,turn,dt)}
function moveCombatShip(p,tx,ty,speed,turn,dt){moveAlienTo(p,tx,ty,speed,turn,dt)}








function restoreDeveloperHp(){if(!dev.hp)return;s.hullCondition=1;if(encounter?.player){encounter.player.hp=encounter.player.max;encounter.startHp=encounter.player.max}}
function playerCrewDamage(n){let p=encounter.player,damage=absorbShield(p,n)*(upgradeHas('hull-plating')?.85:1)/((1+s.shield*.3)*(1+s.hull*.2));if(dev.hp){restoreDeveloperHp();return}p.hp=Math.max(0,p.hp-damage)}
