   alienShot(m,actual==='rear'?'dart':actual,actual==='spray'?aim+(Math.random()-.5)*.38:aim,damage,speeds[actual]||24,range,{life:(lives[actual]||10)/24,hp:hp[actual]||1,home:['plasma','bubble','missile'].includes(actual)?1.1:0});
