 let q={x:m.x+Math.cos(angle)*alienRadius(m)-Math.sin(angle)*side,y:m.y+Math.sin(angle)*alienRadius(m)+Math.cos(angle)*side,vx:Math.cos(angle)*speed+(m.vx||0)*inherit,vy:Math.sin(angle)*speed+(m.vy||0)*inherit,life:range/speed,damage,enemy:true,kind,color,radius:['plasma','bubble','crystal','disc'].includes(kind)?.3:.12,spin:kind==='disc',home:0,source:m,age:0,...options};q.maxLife=q.life;q.baseDamage=damage;q.baseHp=q.hp??1;q.hp??=1;q.baseRadius=q.radius;if(kind==='fireCloud')q.persistent=true;e.shots.push(q);return q;
