 let auto=['lightning','laser'].includes(kind),along=dx*Math.cos(m.a)+dy*Math.sin(m.a),across=Math.abs(dx*Math.sin(m.a)-dy*Math.cos(m.a)),hit=auto||along>=0&&along<=range&&across<(kind==='tongue'?.8:.65);
