function systemInfoMarkup(){if(infoSystem<0)return '';let [name,desc,,action]=SHIP_SYSTEMS[infoSystem],rows=[['Status',s[action]>0?'Installed':'Not purchased'],['Current level',s[action]],['Next level cost',fmt(systemCost(action))+' CR']];
 if(Object.values(SCANNER_KEYS).includes(action)){let level=s[action];rows.push(['Rarity tier',level?scannerRarity(level):'Scanner offline'],['Collection bonus',Math.round((scannerYieldFactor(level)-1)*100)+'%'],['Next rarity level',[1,3,6,10].find(n=>n>level)||'Highest tier reached']);}
 rows.push(...Object.entries(systemRecipe(action)).map(([name,n])=>[name+' required',fmt(s.inventory[name]||0)+' / '+fmt(n)]));rows.push(...systemEffectRows(action));
 if(action==='engine')rows.push(['Ship speed',(shipSpeed()).toFixed(2)+' blocks/s'],['Turn rate',(turnRate()*180/Math.PI).toFixed(1)+'°/s']);
 return `<div class="weapon-choice-backdrop"><section class="weapon-choice" role="dialog" aria-modal="true" aria-label="${name} statistics"><div class="row"><div class="title">${name}</div><button class="choice-close" data-action="closeSystemInfo" aria-label="Close system stats">×</button></div><div class="desc">${desc}</div><dl class="stats-list">`+rows.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')+'</dl></section></div>';
}
function researchLabMarkup(){if(s.researchLevel>0)return '';let cost=researchSpeedCost(),can=(dev.credits||s.credits>=cost.credits)&&Object.entries(cost.materials).every(([name,n])=>dev.materials||craftOwned(name)>=n);return `<div class="card"><div class="title">BUILD RESEARCH LAB</div><div class="desc">Unlock Research and one research slot.</div><div class="system-materials">`+Object.entries(cost.materials).map(([name,n])=>`${name} ${dev.materials?'∞':fmt(s.inventory[name]||0)}/${n}`).join(' · ')+`</div><button class="buy wide" data-action="buildResearchLab" ${can?'':'disabled'}>BUILD · ${fmt(cost.credits)} CR</button></div>`}
function renderSystems(){return researchLabMarkup()+SHIP_SYSTEMS.map(([name,desc,level,action],i)=>`<div class="card weapon-card system-card" data-action="systemInfo:${i}" tabindex="0" role="group" aria-label="${name} stats"><div class="row"><div><div class="weapon-heading"><span class="title">${name}</span><div class="weapon-metrics"><span class="pill">${action?'LV '+s[action]:'PLANNED'}</span></div></div></div>${action?`<button class="buy weapon-price" data-action="systemBuy:${action}" aria-label="Upgrade ${name}" ${!systemCanBuy(action)?'disabled':''}>${fmt(systemCost(action))} CR</button>`:''}</div>${systemMaterialsMarkup(action)}</div>`).join('')+systemInfoMarkup()}
