let mapZoom=1,followShip=true,mapPointers=new Map(),mapGesture=null,suppressMapClickUntil=0;
function mapScale(){return Math.min(cv.clientWidth,cv.clientHeight)*.033*mapZoom}
function mapPoint(e){let r=cv.getBoundingClientRect();return {x:(e.clientX-r.left)*cv.clientWidth/r.width,y:(e.clientY-r.top)*cv.clientHeight/r.height}}
function mapWorld(p){let scale=mapScale();return {x:camera.x+(p.x-cv.clientWidth/2)/scale,y:camera.y+(p.y-cv.clientHeight*.38)/scale}}
function zoomMap(factor,point){let before=point?mapWorld(point):null;mapZoom=Math.max(.35,Math.min(3,mapZoom*factor));if(before){let after=mapWorld(point);camera.x+=before.x-after.x;camera.y+=before.y-after.y;followShip=false}updateMapControls()}
function recenterMap(){followShip=true;let focus=encounter?.type==='merchant'&&encounter.player?encounter.player:ship;camera.x=focus.x;camera.y=focus.y;updateMapControls()}
function updateMapControls(){let b=$('mapRecenter');b.classList.toggle('active',followShip);b.setAttribute('aria-pressed',String(followShip));$('mapZoomIn').disabled=mapZoom>=3;$('mapZoomOut').disabled=mapZoom<=.35}
function beginMapGesture(){let points=[...mapPointers.values()];if(points.length>=2){let a=points[0],b=points[1],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};mapGesture={type:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:mapZoom,world:mapWorld(mid)};followShip=false;suppressMapClickUntil=performance.now()+500}else if(points.length===1){mapGesture={type:'drag',start:points[0],camera:{...camera},moved:false}}else mapGesture=null}
cv.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;cv.setPointerCapture(e.pointerId);mapPointers.set(e.pointerId,mapPoint(e));beginMapGesture()});
cv.addEventListener('pointermove',e=>{if(!mapPointers.has(e.pointerId))return;mapPointers.set(e.pointerId,mapPoint(e));let points=[...mapPointers.values()];if(mapGesture?.type==='pinch'&&points.length>=2){let a=points[0],b=points[1],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};mapZoom=Math.max(.35,Math.min(3,mapGesture.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,mapGesture.distance)));let after=mapWorld(mid);camera.x+=mapGesture.world.x-after.x;camera.y+=mapGesture.world.y-after.y;suppressMapClickUntil=performance.now()+500;updateMapControls()}else if(mapGesture?.type==='drag'){let p=points[0],dx=p.x-mapGesture.start.x,dy=p.y-mapGesture.start.y;if(!mapGesture.moved&&Math.hypot(dx,dy)<6)return;mapGesture.moved=true;followShip=false;camera.x=mapGesture.camera.x-dx/mapScale();camera.y=mapGesture.camera.y-dy/mapScale();suppressMapClickUntil=performance.now()+500;updateMapControls()}});
function endMapPointer(e){if(!mapPointers.has(e.pointerId))return;if(mapGesture?.moved||mapGesture?.type==='pinch')suppressMapClickUntil=performance.now()+500;mapPointers.delete(e.pointerId);beginMapGesture()}
cv.addEventListener('pointerup',endMapPointer);cv.addEventListener('pointercancel',endMapPointer);cv.addEventListener('lostpointercapture',endMapPointer);
cv.addEventListener('wheel',e=>{e.preventDefault();zoomMap(Math.exp(-Math.max(-150,Math.min(150,e.deltaY))*.003),mapPoint(e))},{passive:false});
$('mapZoomIn').addEventListener('click',()=>zoomMap(1.25));$('mapZoomOut').addEventListener('click',()=>zoomMap(1/1.25));$('mapRecenter').addEventListener('click',recenterMap);updateMapControls();

